True def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            if value not in (2, 8):
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    if any(all(value == 2 for value in row) for row in g):
        axis = "row"
        divider = next(r for r, row in enumerate(g) if all(value == 2 for value in row))
    else:
        axis = "column"
        divider = next(c for c in range(w) if all(g[r][c] == 2 for r in range(h)))

    cells = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] not in (background, 2, 8)]
    if not cells:
        return g

    coordinates = [r if axis == "row" else c for r, c, _ in cells]
    low, high = min(coordinates), max(coordinates)
    if high < divider:
        shift = divider - 1 - high
        marker = low + shift - 1
    else:
        shift = divider + 1 - low
        marker = high + shift + 1

    for r, c, _ in cells:
        g[r][c] = background
    for r, c, value in cells:
        if axis == "row":
            g[r + shift][c] = value
        else:
            g[r][c + shift] = value

    if axis == "row" and 0 <= marker < h:
        g[marker] = [8] * w
    elif axis == "column" and 0 <= marker < w:
        for r in range(h):
            g[r][marker] = 8
    return g
